func lastStoneWeight(_ stones: [Int]) -> Int {
    var heap = Heap<Int>(>)          // max-heap, Heap from Kth Largest
    stones.forEach { heap.push($0) }
    while heap.count > 1 {
        let a = heap.pop()!, b = heap.pop()!
        if a != b { heap.push(a - b) }
    }
    return heap.top ?? 0
}
